import java.util.*;
public class Main {
  public static void main(String[] args) {
    Scanner s=new Scanner(System.in); int n=s.nextInt(); int[] a=new int[n]; for(int i=0;i<n;i++)a[i]=s.nextInt(); int l=0,r=n-1; while(l<r){int m=(l+r)/2; if((m&1)==1)m--; if(a[m]==a[m+1])l=m+2; else r=m;} System.out.println(a[l]);
  }
}

import java.util.*;
public class Main {
  public static void main(String[] args) {
    Scanner s=new Scanner(System.in); int n=s.nextInt(); int[] a=new int[n]; for(int i=0;i<n;i++)a[i]=s.nextInt(); int x=s.nextInt(); int l=0,r=n-1,ans=-1; while(l<=r){int m=l+(r-l)/2; if(a[m]==x){ans=m;break;} if(a[l]<=a[m]){if(a[l]<=x&&x<a[m])r=m-1;else l=m+1;}else{if(a[m]<x&&x<=a[r])l=m+1;else r=m-1;}} System.out.println(ans);
  }
}

